import { StyleSheet, Text, View } from 'react-native';

export function LessonCard({ title, minutes }: { title: string; minutes: number }) {
  return (
    <View style={styles.card}>
      <Text style={styles.title}>{title}</Text>
      <Text style={styles.body}>{minutes} минут практики</Text>
    </View>
  );
}

export default function App() {
  return (
    <View style={styles.screen}>
      <Text accessibilityRole="header">Проверка читаемости</Text>
      <LessonCard title="Экран и структуры" minutes={20} />
      <Text style={styles.note}>
        Увеличьте системный шрифт в настройках и откройте экран снова.
      </Text>
    </View>
  );
}

